import{j as t}from"./blog-pages-CPaMOKsP.js";import{I as e}from"./I18nErpPage-DpeGnoBT.js";import"./PillarHubNav-Bef1r64A.js";import"./badge-DyJEh5NS.js";const i={heroBadge:"نظام إدارة فحوصات الاختبارات غير المتلفة",heroTitle:"برنامج تخطيط موارد المؤسسات للاختبارات غير المتلفة في أبوظبي",heroSubtitle:"نظام إدارة الفحص لمنشآت أدنوك",heroIntro:"نظام تخطيط موارد مصمم لشركات الاختبارات غير المتلفة العاملة في منشآت أدنوك في أبوظبي والرويس. أتمتة متابعة متطلبات أدنوك ACS-01 وإصدار تقارير API 510 و API 570.",ctaPrimary:"اطلب عرضًا توضيحيًا لأبوظبي",ctaSecondary:"English version",statCompanies:"شركة فحص تستخدم النظام",statRating:"متوسط تقييم العملاء",statAdminReduction:"تقليل الوقت الإداري",statModules:"وحدات رئيسية",marketContextLabel:"سياق سوق الاختبارات غير المتلفة",painPointsTitle:"لماذا تختار فرق الاختبارات غير المتلفة في أبوظبي نظام أتلانتيس؟",painPointsSubtitle:"ثلاث نقاط ألم تشغيلية حرجة يتم القضاء عليها منذ اليوم الأول",problemLabel:"المشكلة",solutionLabel:"الحل",modulesTitle:"ست وحدات أساسية لشركات الاختبارات غير المتلفة",modulesSubtitle:"كل وحدة مصممة خصيصًا لقطاع التفتيش الصناعي في أبوظبي",roiTitle:"العائد على الاستثمار في أبوظبي",faqTitle:"الأسئلة الشائعة — نظام أتلانتيس في أبوظبي",alsoServingTitle:"خدمات أخرى",finalCtaTitle:"هل أنت مستعد لتحديث عمليات الاختبارات غير المتلفة في أبوظبي؟",finalCtaBody:"انضم إلى شركات التفتيش العاملة في منشآت أدنوك بالرويس وداس وزركوه التي استبدلت جداول البيانات بنظام أتلانتيس.",finalCtaPrimary:"اطلب عرضًا توضيحيًا",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function n(){return t.jsx(e,{lang:"ar",dir:"rtl",city:"أبوظبي",countryCode:"AE",countryName:"الإمارات العربية المتحدة",slug:"ndt-erp-abu-dhabi",canonicalPath:"/ar/ndt-erp-abu-dhabi",englishPath:"/ndt-erp-abu-dhabi",pageTitle:"برنامج NDT في أبوظبي | نظام إدارة فحص منشآت أدنوك | أتلانتيس NDT",pageDescription:"نظام تخطيط موارد للاختبارات غير المتلفة لشركات الفحص العاملة في منشآت أدنوك بأبوظبي والرويس. متابعة شهادات ASNT و CSWIP، إصدار تقارير متوافقة مع ACS-01.",keywords:"برنامج NDT أبوظبي, نظام إدارة فحص الإمارات, أدنوك, الرويس, ACS-01, ASNT, ISO 9712, شركة فحص أبوظبي",marketContext:"تتحكم إمارة أبوظبي في 94٪ من احتياطيات الإمارات النفطية وتستضيف مجمع الرويس الصناعي المتكامل التابع لشركة بترول أبوظبي الوطنية (أدنوك)، مما يجعلها واحدة من أكثف مناطق نشاط التفتيش في الشرق الأوسط. يجب على شركات خدمات الفحص التي تدعم منشآت أدنوك الالتزام بمعايير الشركة الإماراتية الصارمة ACS-01 الخاصة بالتأهيل وصيغ التقارير والاحتفاظ بالبيانات. يوفر نظام أتلانتيس لتخطيط موارد الاختبارات غير المتلفة لفرق الفحص في أبوظبي لوحة قيادة للامتثال تتتبع متطلبات API و ASME ومتطلبات أدنوك الخاصة، مما يقلل العبء الإداري ويضمن الجاهزية للتدقيق في جميع الأوقات. كما يدعم النظام التكامل مع متطلبات الشركات التشغيلية التابعة لأدنوك بما في ذلك أدنوك للحفر وأدنوك البحرية وأدنوك للتكرير، فضلًا عن المتطلبات القديمة لشركتي ZADCO و ADMA-OPCO التي ما تزال تنطبق على بعض الأصول البحرية في حقول زاكوم العلوي وأم الشيف.",roiBody:"تبلّغ شركات الفحص في أبوظبي التي اعتمدت نظام أتلانتيس عن تقليل الوقت الإداري بنسبة 42% خلال الأشهر الستة الأولى، وانخفاض زمن إعداد تقرير API 510 من ثلاث ساعات إلى أربع دقائق. اختفت تنبيهات انتهاء شهادات ASNT و CSWIP المفاجئة بفضل التذكيرات الآلية، وأصبح إعداد ملف تدقيق أدنوك متاحًا بنقرة واحدة قبل كل زيارة من فريق تكامل الأصول. لفريق فحص مكوّن من عشرين فنيًا يخدم منشآت الرويس، يمثل ذلك توفيرًا سنويًا يتراوح بين 120,000 و160,000 درهم إماراتي، إضافة إلى قيمة الاحتفاظ باعتماد المورد لدى أدنوك.",painPoints:[{title:"متطلبات أدنوك ACS-01 المتغيرة",problem:"تتطلب أدنوك التزامًا صارمًا بمعيار الشركة ACS-01 لإعداد تقارير الفحص وتأهيل المفتشين، مع تحديثات دورية تصعب على شركات الفحص متابعتها يدويًا.",solution:"يحتوي نظام أتلانتيس على مكتبة قوالب ACS-01 محدثة باستمرار، مع تنبيهات تلقائية عند صدور إصدارات جديدة من المعايير لضمان الامتثال المستمر."},{title:"العمليات البحرية في حقول زاكوم وأم الشيف",problem:"تواجه فرق الفحص العاملة على منصات أدنوك البحرية تحدي الاتصال المتقطع وضرورة تسليم التقارير بصيغ محددة لمشغّلي ZADCO و ADMA السابقين.",solution:"يعمل التطبيق دون اتصال على المنصات البحرية ويتزامن تلقائيًا عند العودة إلى الشاطئ، مع قوالب جاهزة لصيغ تقارير ZADCO و ADMA-OPCO القديمة."},{title:"تدقيق فريق تكامل الأصول لدى أدنوك",problem:"تجري أدنوك مراجعات فصلية لفرق الفحص المعتمدة، تتطلب تقديم سجلات تاريخية كاملة للفحص ومؤهلات الموظفين خلال أيام معدودة.",solution:"يولّد نظام أتلانتيس حزمة تدقيق كاملة لأدنوك تشمل تاريخ فحص الأصول وسجلات تأهيل الأفراد وشهادات المعايرة بنقرة واحدة في أي وقت."}],modules:[{title:"جدولة الفحص وإدارة أوامر العمل",description:"أتمتة احتساب فترات الفحص وفقًا لمعايير API و ASME ومتطلبات أدنوك ACS-01. تخصيص الفنيين والمعدات لأوامر العمل في ثوانٍ.",features:["احتساب تلقائي لفترات API 510/570/653","جدولة الفحص القائم على المخاطر","مصفوفة توفر الفنيين البحريين","تدفقات اعتماد أوامر عمل أدنوك","وصول ميداني للمفتشين عبر الهاتف"]},{title:"تتبع شهادات الأفراد",description:"مركز سجلات شهادات ASNT و ISO 9712 و PCN و CSWIP وشهادات أدنوك ACS-01 للفنيين البحريين والبريين.",features:["تنبيهات انتهاء ASNT و CSWIP","متابعة ISO 9712 و PCN","مصفوفة المؤهلات وفق ACS-01","رسائل تذكير تلقائية بالتجديد","تصدير شهادات PDF جاهزة للتدقيق"]},{title:"إصدار تقارير الفحص",description:"أنشئ تقارير فحص احترافية بصيغة PDF وفقًا لمعايير API و ASME وقوالب أدنوك ACS-01 و ZADCO/ADMA.",features:["قوالب تقارير الأوعية الضاغطة API 510","صيغ فحص الأنابيب API 570","تقارير فحص الخزانات API 653","قوالب أدنوك ACS-01 المعتمدة","تكامل التوقيع الرقمي والختم"]},{title:"إدارة بيانات التآكل",description:"سجّل قراءات السماكة ومعدلات التآكل وحسابات العمر المتبقي لأصول الرويس وداس وزركوه.",features:["قاعدة بيانات قياسات السماكة بالموجات فوق الصوتية","مخططات اتجاه معدل التآكل","احتساب العمر المتبقي","تنبيهات نسبة فقدان السماكة","تصدير تقييم API 579"]},{title:"سجل الأصول وإدارة المعدات",description:"احتفظ بسجل رقمي كامل للأصول مع تتبع حالة معايرة المعدات وأدوات الفحص.",features:["هيكلية أصول مرتبطة بمخططات P&ID","متتبع تواريخ استحقاق المعايرة","وسم الأصول برموز QR","سجل فحص تاريخي لكل أصل","تصنيف المخاطر"]},{title:"لوحة الامتثال",description:"رؤية فورية لامتثال متطلبات أدنوك و API و ISO 55000 في الإمارات.",features:["لوحة تنبيه الفحوصات المتأخرة","نظرة عامة على حالة الامتثال متعدد العملاء","تقارير مؤشرات الأداء الرئيسية","تنبيهات تغييرات اللوائح","تقارير ملخص تنفيذي"]}],integrations:["تكامل مع معايير أدنوك ACS-01","صيغ تقارير ZADCO و ADMA-OPCO","ربط بوابة موردي أدنوك ICAPS","تكامل SAP S/4HANA","ربط مع منصة IRIS AIM","تكامل Maximo CMMS","متطلبات OPITO BOSIET للعمليات البحرية","متطلبات اتحاد الإمارات للخدمات البحرية"],faqs:[{question:"هل يدعم النظام متطلبات أدنوك ACS-01 الكاملة؟",answer:"نعم. يحتوي النظام على مكتبة قوالب ACS-01 محدثة باستمرار، تشمل صيغ تقارير الفحص للأوعية الضاغطة والأنابيب وخزانات التخزين والمعدات الدوارة. يتم تحديث القوالب تلقائيًا عند صدور إصدارات جديدة من المعيار، ويتلقى المشرفون تنبيهات للمراجعة قبل تطبيق التحديثات على التقارير النشطة."},{question:"هل يعمل التطبيق على المنصات البحرية في حقول زاكوم وأم الشيف؟",answer:"نعم. يتضمن النظام وضع جمع البيانات دون اتصال للعمل على المنصات البحرية، مع مزامنة تلقائية عند العودة إلى الشاطئ. كما يحتوي على قوالب تقارير قديمة لـ ZADCO و ADMA-OPCO التي ما تزال مستخدمة لبعض الأصول البحرية، إضافة إلى متابعة شهادات OPITO BOSIET للفنيين البحريين."},{question:"هل يدعم النظام تكامل بوابة موردي أدنوك ICAPS؟",answer:"نعم. يدعم النظام تصدير التقارير بصيغ متوافقة مع بوابة موردي أدنوك ICAPS، مع إمكانية الرفع الآلي المباشر عبر واجهة برمجة التطبيقات لشركات الفحص ذات حجم التقارير العالي. يضمن هذا التكامل تسليم التقارير في الوقت المناسب وتجنب الغرامات المرتبطة بالتأخير."},{question:"ما مدة التنفيذ لشركة فحص جديدة معتمدة من أدنوك؟",answer:"يستغرق التنفيذ النموذجي لشركة فحص في أبوظبي من خمسة إلى سبعة أسابيع، شاملًا ترحيل البيانات التاريخية وتدريب الفرق وتكامل قوالب التقارير الخاصة بأدنوك ACS-01. يوفر فريق التنفيذ تدريبًا مكثفًا في الموقع لضمان الاعتماد السريع وعدم التأثير على المشاريع النشطة."}],ui:i})}export{n as default};
